mapper.select:
SELECT pi.PID_NO ,pi.MEMBER_NO ,pi.ORG_NO ,om.ORG_CD ,AES_DECRYPT(FROM_BASE64(pi.PID_ENC) , ei.ENC_KEY) AS PID ,pi.PID_ENC ,pi.PID_STS_CD ,pi.JOIN_DT ,pi.STOP_DT ,pi.REG_USER_ID ,pi.REG_DT ,pi.LAST_MOD_USER_ID ,pi.LAST_MOD_DT FROM T_MEMBER_PID pi INNER JOIN T_MEMBER_MST mm ON mm.MEMBER_NO = pi.MEMBER_NO INNER JOIN T_ORG_MST om ON om.ORG_NO = pi.ORG_NO
AND om.ORG_CD = #{orgCd}
AND om.ORG_NO = #{orgNo}
INNER JOIN T_ENC_INFO ei ON ei.TARGET_GB_CD = 'ORG' AND mm.ORG_NO = CAST(ei.TARGET_VAL AS UNSIGNED) WHERE 1 = 1
AND pi.PID_NO = #{pidNo}
AND pi.MEMBER_NO = #{memberNo}
AND pi.PID_ENC = TO_BASE64(AES_ENCRYPT(#{pid}, ei.ENC_KEY))
AND pi.PID_ENC = #{pidEnc}

SELECT T.ROW_NUM AS ROW_NUM ,T.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY pi.PID_NO) ROW_NUM ,pi.PID_NO ,pi.MEMBER_NO ,pi.ORG_NO ,om.ORG_CD ,AES_DECRYPT(FROM_BASE64(pi.PID_ENC) , ei.ENC_KEY) AS PID ,pi.PID_ENC ,pi.PID_STS_CD ,pi.JOIN_DT ,pi.STOP_DT ,pi.REG_USER_ID ,pi.REG_DT ,pi.LAST_MOD_USER_ID ,pi.LAST_MOD_DT FROM T_MEMBER_PID pi INNER JOIN T_MEMBER_MST mm ON mm.MEMBER_NO = pi.MEMBER_NO INNER JOIN T_ORG_MST om ON om.ORG_NO = pi.ORG_NO
AND om.ORG_CD = #{orgCd}
AND om.ORG_NO = #{orgNo}
INNER JOIN T_ENC_INFO ei ON ei.TARGET_GB_CD = 'ORG' AND mm.ORG_NO = CAST(ei.TARGET_VAL AS UNSIGNED) WHERE 1 = 1
AND pi.PID_NO = #{pidNo}
AND pi.MEMBER_NO = #{memberNo}
AND pi.PID_ENC = TO_BASE64(AES_ENCRYPT(#{pid}, ei.ENC_KEY))
AND pi.PID_ENC = #{pidEnc}
ORDER BY pi.PID_NO ) T
WHERE T.ROW_NUM BETWEEN #{startIndex} AND #{endIndex}
